"use client";
/**
 * Add a credential and rotate one. The secret fields are password inputs that the page never fills:
 * a secret goes in, it never comes back. A webhook secret is generated by Flow and shown here once,
 * from the action's answer (kept in this component's state only, never in a URL).
 */
import { useActionState, useState } from "react";
import { createCredentialAction, rotateCredentialAction } from "@/app/actions";
import type { CredentialFormState } from "@/lib/credentials/form";
import type { CredentialKind } from "@/lib/credentials/store";

const MESSAGES: Record<string, string> = {
  invalid_credential: "Those fields don't fit: check each one.",
  credential_name_taken: "A credential with that name exists already.",
  credential_not_found: "That credential doesn't exist any more.",
  credentials_unavailable: "Credentials aren't set up on this server.",
  forbidden: "403 Forbidden: you don't have the permission",
  not_found: "Not found.",
};

function Answer({ state }: { state: CredentialFormState }) {
  if (state.status === "error")
    return (
      <p className="notice bad" role="alert" data-testid="credential-error">
        {MESSAGES[state.error] ?? "Something went wrong."}
        {state.permission ? <span className="perm"> {state.permission}</span> : null}
      </p>
    );
  if (state.status === "done" && state.secret)
    return (
      <div className="notice warn" role="status" data-testid="shown-once">
        <p>Copy this secret now: it won&apos;t be shown again.</p>
        <pre className="mono" data-testid="secret">
          {state.secret}
        </pre>
      </div>
    );
  if (state.status === "done")
    return (
      <p className="notice" role="status" data-testid="credential-saved">
        Saved.
      </p>
    );
  return null;
}

/** The secret fields of a kind; empty, never prefilled. */
function SecretFields({ kind, prefix }: { kind: CredentialKind; prefix: string }) {
  if (kind === "smtp")
    return (
      <>
        <label htmlFor={`${prefix}-username`}>Username</label>
        <input id={`${prefix}-username`} name="username" autoComplete="off" required maxLength={256} />
        <label htmlFor={`${prefix}-password`}>Password</label>
        <input
          id={`${prefix}-password`}
          name="password"
          type="password"
          autoComplete="new-password"
          required
          maxLength={1024}
        />
      </>
    );
  if (kind === "github-token" || kind === "gitlab-token")
    return (
      <>
        <label htmlFor={`${prefix}-token`}>Token</label>
        <input id={`${prefix}-token`} name="token" type="password" autoComplete="off" required maxLength={255} />
      </>
    );
  return <p className="muted hint">Flow generates the secret and shows it once.</p>;
}

export function AddCredentialForm() {
  const [state, action, pending] = useActionState(createCredentialAction, { status: "idle" });
  const [kind, setKind] = useState<CredentialKind>("smtp");
  return (
    <form action={action} className="card" aria-labelledby="add-heading" data-testid="add-credential">
      <h2 id="add-heading">Add a credential</h2>
      <Answer state={state} />
      <label htmlFor="add-kind">Kind</label>
      <select id="add-kind" name="kind" value={kind} onChange={(e) => setKind(e.target.value as CredentialKind)}>
        <option value="smtp">SMTP</option>
        <option value="github-token">GitHub token</option>
        <option value="gitlab-token">GitLab token (read issues)</option>
        <option value="webhook-secret">Webhook secret</option>
      </select>
      <label htmlFor="add-name">Name</label>
      <input id="add-name" name="name" required maxLength={100} />
      {kind === "smtp" ? (
        <>
          <label htmlFor="add-host">Host</label>
          <input id="add-host" name="host" required placeholder="smtp.example.com" />
          <label htmlFor="add-port">Port</label>
          <input id="add-port" name="port" type="number" min={1} max={65535} defaultValue={587} required />
          <label htmlFor="add-mode">Mode</label>
          <select id="add-mode" name="mode" defaultValue="starttls">
            <option value="starttls">STARTTLS</option>
            <option value="tls">TLS</option>
            <option value="none">None (local development, a loopback host only)</option>
          </select>
          <label htmlFor="add-from">From</label>
          <input id="add-from" name="from" type="email" required />
        </>
      ) : null}
      {kind === "github-token" ? (
        <>
          <label htmlFor="add-repos">Allowed repositories</label>
          <textarea id="add-repos" name="repos" rows={3} required placeholder="owner/repo" />
        </>
      ) : null}
      {kind === "gitlab-token" ? (
        <>
          <label htmlFor="add-projects">Allowed gitlab.com projects</label>
          <textarea id="add-projects" name="projects" rows={3} required placeholder="group/project" />
          <p className="muted hint">
            A read-only token (read_api). Flow uses it only to read an issue to draft a workflow from.
          </p>
        </>
      ) : null}
      <SecretFields kind={kind} prefix="add" />
      <div className="actions">
        <button type="submit" disabled={pending}>
          Add
        </button>
      </div>
    </form>
  );
}

export function RotateCredentialForm({ id, kind, name }: { id: string; kind: CredentialKind; name: string }) {
  const [state, action, pending] = useActionState(rotateCredentialAction, { status: "idle" });
  return (
    <details data-testid="rotate">
      <summary>Rotate</summary>
      <form action={action} aria-label={`Rotate ${name}`}>
        <input type="hidden" name="credentialId" value={id} />
        <input type="hidden" name="kind" value={kind} />
        <Answer state={state} />
        <SecretFields kind={kind} prefix={`rotate-${id}`} />
        <button type="submit" className="secondary" disabled={pending}>
          {kind === "webhook-secret" ? "Generate a new secret" : "Save the new secret"}
        </button>
      </form>
    </details>
  );
}
